// === Tab: darkHole ===
// Created for the WCCC on the "Void" theme.

var stars = [];
var config = {
  numStars: 600,
  gravitationalConstant: 150,
  blackHoleScale: 0.2,
  backgroundFade: 15,
  accretionDiskLayers: 50,
};

function setup() {
  createCanvas(windowWidth, windowHeight);
  noStroke();
  initializeStars();
}

function draw() {
  background(0, config.backgroundFade);

  const centerX = width / 2;
  const centerY = height / 2;
  const blackHoleDiameter = calculateBlackHoleDiameter();

  updateAndDrawStars(centerX, centerY, blackHoleDiameter);
  drawAccretionDisk(centerX, centerY, blackHoleDiameter);
  drawBlackHole(centerX, centerY, blackHoleDiameter);
}

function windowResized() {
  resizeCanvas(windowWidth, windowHeight);
  initializeStars(); // Reinitialize stars to adapt to new dimensions
}

// --- Helper Functions ---

// Initialize stars around the black hole
function initializeStars() {
  stars = [];
  var centerX = width / 2;
  var centerY = height / 2;
  var blackHoleDiameter = calculateBlackHoleDiameter();
  for (let i = 0; i < config.numStars; i++) {
    createStar(centerX, centerY, blackHoleDiameter);
  }
}

// Calculate the diameter of the black hole
function calculateBlackHoleDiameter() {
  return max(width, height) * config.blackHoleScale;
}

// Create a new star
function createStar(centerX, centerY, blackHoleDiameter) {
  let distFromCenter = random(blackHoleDiameter / 2, width / 2);
  let angle = random(TWO_PI);
  stars.push({
    x: centerX + distFromCenter * cos(angle),
    y: centerY + distFromCenter * sin(angle),
    size: random(1, 3),
    vx: -sqrt(50 / distFromCenter) * sin(angle),
    vy: sqrt(50 / distFromCenter) * cos(angle),
    color: color(random(150, 255)),
  });
}

// Update and draw all stars
function updateAndDrawStars(centerX, centerY, blackHoleDiameter) {
  for (let i = stars.length - 1; i >= 0; i--) {
    let star = stars[i];
    updateStar(star, centerX, centerY, blackHoleDiameter);
    if (isInsideBlackHole(star, centerX, centerY, blackHoleDiameter)) {
      stars.splice(i, 1); // Remove stars inside the black hole
      createStar(centerX, centerY, blackHoleDiameter); // Add a replacement
    } else {
      drawStar(star, blackHoleDiameter);
    }
  }
}

// Check if a star is inside the black hole
function isInsideBlackHole(star, centerX, centerY, blackHoleDiameter) {
  let distanceToCenter = dist(star.x, star.y, centerX, centerY);
  return distanceToCenter <= blackHoleDiameter / 2;
}

// Update star position based on gravitational forces
function updateStar(star, centerX, centerY, blackHoleDiameter) {
  let dx = centerX - star.x;
  let dy = centerY - star.y;
  let distSq = dx * dx + dy * dy;
  let dist = sqrt(distSq);

  if (dist > blackHoleDiameter / 2) {
    let forceMagnitude = config.gravitationalConstant / distSq;
    let radialForceX = (dx / dist) * forceMagnitude;
    let radialForceY = (dy / dist) * forceMagnitude;

    star.vx += radialForceX;
    star.vy += radialForceY;
  }

  star.x += star.vx;
  star.y += star.vy;
}

// Draw a star with a size scaled by its distance
function drawStar(star, blackHoleDiameter) {
  let distToCenter = dist(width / 2, height / 2, star.x, star.y);
  let apparentSize = star.size * (1 + 2 * blackHoleDiameter / distToCenter);
  fill(star.color);
  ellipse(star.x, star.y, apparentSize, apparentSize);
}

// Draw the accretion disk with dynamic colors
function drawAccretionDisk(centerX, centerY, blackHoleDiameter) {
  for (let i = 0; i < config.accretionDiskLayers; i++) {
    let diameter = blackHoleDiameter * (1 + i / 10);
    let hue = map(i, 0, config.accretionDiskLayers, 0, 255);
    let alpha = map(i, 0, config.accretionDiskLayers, 128, 0);
    stroke(color(hue, 255, 255, alpha));
    strokeWeight(2 + i * 0.05);
    noFill();
    ellipse(centerX, centerY, diameter, diameter);
  }
}

// Draw the central black hole
function drawBlackHole(centerX, centerY, blackHoleDiameter) {
  fill(0);
  noStroke();
  ellipse(centerX, centerY, blackHoleDiameter);
}
